      "timepoint_unit": "short-term",
      "evidence": [
        {
          "block_id": "b00044",
          "quote": "Direct ex vivo brain slice exposure to an extremely low-frequency electromagnetic field caused reductions in amplitude of the evoked potentials both in the hippocampus (A) and in the neocortex (B)[* denotes significant differences at a level of P < 0.05 compared to the untreated control.Data are presented as means � SEM]."
        }
      ]
    },
    {
